--
-- Structure de la table `academy_homepage_config`
--

CREATE TABLE `academy_homepage_config` (
  `faction_key` varchar(64) NOT NULL,
  `hero_title` varchar(255) DEFAULT NULL COMMENT 'Titre principal (héro)',
  `hero_subtitle` varchar(255) DEFAULT NULL COMMENT 'Sous-titre court',
  `presentation_text` longtext DEFAULT NULL COMMENT 'Texte riche de présentation (HTML sanitized)',
  `cta_primary_label` varchar(64) DEFAULT 'Déposer une candidature',
  `cta_secondary_label` varchar(64) DEFAULT 'Passer le QCM',
  `accent_color` varchar(9) DEFAULT NULL COMMENT 'Couleur secondaire personnalisée',
  `motto` varchar(255) DEFAULT NULL COMMENT 'Devise / slogan court',
  `is_published` tinyint(1) NOT NULL DEFAULT 1,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `academy_homepage_config`
--

INSERT INTO `academy_homepage_config` (`faction_key`, `hero_title`, `hero_subtitle`, `presentation_text`, `cta_primary_label`, `cta_secondary_label`, `accent_color`, `motto`, `is_published`, `updated_by`, `updated_at`) VALUES
('DOJ', 'Department of Justice', 'Garant de l\'État de droit', '<p>Le DOJ supervise les institutions judiciaires, dirige les enquêtes fédérales sensibles et défend l\'État de droit en toutes circonstances.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'L\'autorité de la loi', 1, NULL, '2026-05-10 11:35:18'),
('GRUPP6', 'Grupp 6', 'Sécurité privée d\'excellence', '<p>Grupp 6 est la principale société de sécurité privée de Los Santos : convoyage, gardiennage, escorte. Discipline et discrétion sont nos maîtres-mots.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Sécurité, discrétion, fiabilité', 1, NULL, '2026-05-10 11:35:18'),
('IRS_TREASURY', 'IRS — Department of the Treasury', 'L\'économie au service de la collectivité', '<p>L\'IRS Treasury veille à l\'application du droit fiscal et au bon usage des deniers publics. Un métier exigeant, rigoureux et passionnant.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Service. Intégrité. Excellence.', 1, NULL, '2026-05-10 11:35:18'),
('LSFD', 'Los Santos Fire Department', 'Combattre le feu, sauver des vies', '<p>Pompiers, secouristes, plongeurs : intégrez le LSFD et faites partie d\'une équipe soudée et engagée.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Courage et engagement', 1, NULL, '2026-05-10 11:35:18'),
('LSPD', 'Los Santos Police Department', 'Servir et protéger Los Santos', '<p>Le LSPD est la principale force de police de Los Santos. Nous recrutons des hommes et des femmes intègres, prêts à faire respecter la loi avec professionnalisme.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Servir et protéger', 1, NULL, '2026-05-10 11:35:18'),
('LSSD', 'Los Santos Sheriffs Department', 'L\'autorité du shérif sur le comté', '<p>Le LSSD est l\'institution shérifale du comté de Los Santos. Patrouilles, transport pénitentiaire, sécurité judiciaire : un quotidien varié.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Pour le comté, par le comté', 1, NULL, '2026-05-10 11:35:18'),
('MARSHALS', 'United States Marshals', 'L\'élite fédérale au service de la Justice', '<p>Les US Marshals exécutent les mandats fédéraux, protègent les témoins et assurent la sécurité des cours fédérales.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Justice, intégrité, service', 1, NULL, '2026-05-10 11:35:18'),
('SAMS', 'Service Ambulancier & Médical', 'Sauver des vies au quotidien', '<p>Le SAMS regroupe les médecins, infirmiers et paramédicaux qui interviennent en urgence sur tout Los Santos.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Premiers à arriver, derniers à partir', 1, NULL, '2026-05-10 11:35:18'),
('SUPERIOR_COURT_SA', 'Superior Court of San Andreas', 'La justice rendue au nom du peuple', '<p>La Cour supérieure recrute des juges, greffiers et auxiliaires de justice pour servir l\'institution judiciaire de l\'État.</p>', 'Déposer une candidature', 'Passer le QCM', NULL, 'Audi alteram partem', 1, NULL, '2026-05-10 11:35:18');

