-- Déchargement des données de la table `academy_homepage_faq`
--

INSERT INTO `academy_homepage_faq` (`id`, `faction_key`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'LSPD', 'Comment rejoindre le LSPD ?', '<p>Cliquez sur « Déposer une candidature » sur cette page. Notre équipe étudiera votre dossier et vous recontactera sous 72h.</p>', 1, 1, '2026-05-10 11:35:18', '2026-05-10 11:35:18'),
(2, 'LSPD', 'Quels sont les prérequis ?', '<p>Avoir un casier judiciaire vierge, être citoyen de Los Santos depuis au moins une semaine et faire preuve de motivation lors de l\'entretien.</p>', 2, 1, '2026-05-10 11:35:18', '2026-05-10 11:35:18'),
(3, 'LSPD', 'Combien de temps dure le recrutement ?', '<p>Le processus complet dure environ 2 semaines : étude du dossier, entretien, formation initiale puis QCM final.</p>', 3, 1, '2026-05-10 11:35:18', '2026-05-10 11:35:18');

