--
-- Structure de la table `arrest_warrants`
--

CREATE TABLE `arrest_warrants` (
  `id` int(11) NOT NULL,
  `citizen_id` int(11) NOT NULL,
  `warrant_type` enum('arrest','search','seizure') NOT NULL COMMENT 'Arrêt, Perquisition, Saisie',
  `offense_code` varchar(50) NOT NULL,
  `offense_title` varchar(255) NOT NULL,
  `reason_rich` text NOT NULL COMMENT 'Motif détaillé',
  `severity` enum('low','medium','high','critical') DEFAULT 'medium',
  `bail_amount` decimal(10,2) DEFAULT 0.00 COMMENT 'Montant caution',
  `issued_by` int(11) NOT NULL COMMENT 'Juge émetteur',
  `approved_by` int(11) DEFAULT NULL COMMENT 'Procureur',
  `issued_date` datetime DEFAULT current_timestamp(),
  `expiration_date` datetime DEFAULT NULL COMMENT 'Date d''expiration',
  `status` enum('active','executed','cancelled','expired') DEFAULT 'active',
  `execution_date` datetime DEFAULT NULL COMMENT 'Date d''exécution',
  `executed_by` int(11) DEFAULT NULL COMMENT 'Agent exécuteur',
  `notes` text DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

