--
-- Structure de la table `court_cases`
--

CREATE TABLE `court_cases` (
  `id` int(11) NOT NULL,
  `case_number` varchar(50) NOT NULL,
  `case_title` varchar(255) NOT NULL,
  `case_type` enum('criminal','civil','administrative') NOT NULL,
  `defendant_id` int(11) NOT NULL,
  `plaintiff_id` int(11) DEFAULT NULL COMMENT 'Plaignant (civil)',
  `charges` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Liste des charges {code, title}' CHECK (json_valid(`charges`)),
  `description_rich` text DEFAULT NULL,
  `prosecutor_id` int(11) DEFAULT NULL COMMENT 'Procureur',
  `defense_attorney_id` int(11) DEFAULT NULL COMMENT 'Avocat défense',
  `judge_id` int(11) DEFAULT NULL COMMENT 'Juge',
  `hearing_date` datetime DEFAULT NULL COMMENT 'Date d''audience',
  `verdict` enum('pending','guilty','not_guilty','dismissed','settled') DEFAULT 'pending',
  `verdict_date` datetime DEFAULT NULL,
  `verdict_details` text DEFAULT NULL COMMENT 'Détails du verdict',
  `sentence_id` int(11) DEFAULT NULL COMMENT 'Lien vers sentence',
  `status` enum('filed','scheduled','in_progress','concluded','appealed') DEFAULT 'filed',
  `priority` enum('low','normal','high','urgent') DEFAULT 'normal',
  `evidence_urls` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`evidence_urls`)),
  `court_notes` text DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
