--
-- Structure de la table `criminal_records`
--

CREATE TABLE `criminal_records` (
  `id` int(11) NOT NULL,
  `citizen_id` int(11) NOT NULL,
  `record_type` enum('felony','misdemeanor','infraction','warning') NOT NULL COMMENT 'Type: Crime, Délit, Contravention, Avertissement',
  `offense_code` varchar(50) NOT NULL COMMENT 'Code pénal (ex: PC 487)',
  `offense_title` varchar(255) NOT NULL COMMENT 'Titre du délit',
  `description_rich` text DEFAULT NULL COMMENT 'Description détaillée HTML',
  `severity` int(11) DEFAULT 1 COMMENT 'Gravité 1-5',
  `fine_amount` decimal(10,2) DEFAULT 0.00 COMMENT 'Amende',
  `jail_time` int(11) DEFAULT 0 COMMENT 'Temps de prison en mois',
  `points` int(11) DEFAULT 0 COMMENT 'Points sur permis',
  `officer_id` int(11) NOT NULL COMMENT 'Agent verbalisateur',
  `case_number` varchar(50) DEFAULT NULL COMMENT 'Numéro de dossier',
  `incident_date` datetime NOT NULL COMMENT 'Date des faits',
  `conviction_date` datetime DEFAULT current_timestamp() COMMENT 'Date de condamnation',
  `status` enum('active','served','pardoned','appealed') DEFAULT 'active',
  `notes` text DEFAULT NULL COMMENT 'Notes additionnelles',
  `evidence_urls` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'URLs des preuves' CHECK (json_valid(`evidence_urls`)),
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

