--
-- Structure de la table `death_certificates`
--

CREATE TABLE `death_certificates` (
  `id` int(11) NOT NULL,
  `deceased_firstname` varchar(100) NOT NULL COMMENT 'Prénom du défunt',
  `deceased_lastname` varchar(100) NOT NULL COMMENT 'Nom du défunt',
  `deceased_age` int(11) DEFAULT NULL COMMENT 'Âge du défunt',
  `date_of_death` datetime NOT NULL COMMENT 'Date et heure du décès',
  `place_of_death` varchar(255) NOT NULL COMMENT 'Lieu du décès',
  `cause_of_death` text NOT NULL COMMENT 'Cause du décès',
  `circumstances` text DEFAULT NULL COMMENT 'Circonstances détaillées',
  `doctor_id` int(11) NOT NULL COMMENT 'Médecin certifiant',
  `witness_name` varchar(200) DEFAULT NULL COMMENT 'Témoin éventuel',
  `autopsy_requested` tinyint(1) DEFAULT 0 COMMENT 'Autopsie demandée',
  `certificate_number` varchar(50) DEFAULT NULL COMMENT 'Numéro de certificat',
  `status` enum('draft','certified','archived') DEFAULT 'certified',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

