`agent_id` int(11)
,`agent_nom` varchar(100)
,`rank` varchar(100)
,`nb_ventes` bigint(21)
,`nb_locations` bigint(21)
,`comm_ventes` decimal(32,2)
,`comm_locations` decimal(32,2)
,`commission_totale` decimal(33,2)
);

