--
-- Structure de la table `dynasty_ventes`
--

CREATE TABLE `dynasty_ventes` (
  `id` int(11) NOT NULL,
  `reference` varchar(30) NOT NULL,
  `bien_id` int(11) NOT NULL,
  `agent_id` int(11) NOT NULL,
  `acheteur_nom` varchar(255) NOT NULL,
  `acheteur_id_jeu` varchar(50) DEFAULT NULL,
  `acheteur_contact` varchar(100) DEFAULT NULL,
  `prix_initial` decimal(12,2) NOT NULL,
  `prix_negocie` decimal(12,2) NOT NULL,
  `remise` decimal(10,2) DEFAULT 0.00,
  `mode_paiement` enum('especes','virement','cheque','financement') DEFAULT 'especes',
  `date_vente` date NOT NULL,
  `commission_pct` decimal(5,2) DEFAULT 5.00,
  `commission_amt` decimal(10,2) DEFAULT 0.00,
  `frais_agence` decimal(10,2) DEFAULT 0.00,
  `statut` enum('en_cours','signe','acte_final','annule') DEFAULT 'en_cours',
  `notes` text DEFAULT NULL,
  `invoice_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

