--
-- Structure de la table `faction_division_members`
--

CREATE TABLE `faction_division_members` (
  `id` int(10) UNSIGNED NOT NULL,
  `division_id` int(10) UNSIGNED NOT NULL,
  `user_id` int(11) NOT NULL,
  `division_grade_id` int(10) UNSIGNED DEFAULT NULL COMMENT 'FK → faction_division_grades.id, NULL tant que pas assigné',
  `role` varchar(120) DEFAULT NULL COMMENT 'Rôle libre (Commanding Officer, Instructeur…)',
  `joined_date` date NOT NULL DEFAULT curdate(),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

