--
-- Structure de la table `faction_grades`
--

CREATE TABLE `faction_grades` (
  `id` int(10) UNSIGNED NOT NULL,
  `faction_id` int(10) UNSIGNED NOT NULL,
  `name` varchar(100) NOT NULL,
  `rank_order` smallint(6) NOT NULL DEFAULT 99,
  `can_recruit` tinyint(1) NOT NULL DEFAULT 0,
  `can_manage_stock` tinyint(1) NOT NULL DEFAULT 0,
  `can_manage_finances` tinyint(1) NOT NULL DEFAULT 0,
  `is_owner` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'PDG/Patron',
  `is_ceo` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Co-PDG/Co-Patron',
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

