--
-- Structure de la table `heavy_impound_fourriere`
--

CREATE TABLE `heavy_impound_fourriere` (
  `id` int(11) NOT NULL,
  `profile_id` int(11) DEFAULT NULL COMMENT 'FK → profiles.id',
  `plaque` varchar(20) NOT NULL,
  `modele` varchar(100) NOT NULL,
  `heure_entree` datetime NOT NULL,
  `statut` enum('en_fourriere','sorti') NOT NULL DEFAULT 'en_fourriere',
  `heure_sortie` datetime DEFAULT NULL,
  `montant_facture` decimal(10,2) DEFAULT NULL,
  `sorti_par` int(11) DEFAULT NULL COMMENT 'FK → users.id',
  `added_by` int(11) DEFAULT NULL COMMENT 'FK → users.id',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `heavy_impound_fourriere_tarif`
--

CREATE TABLE `heavy_impound_fourriere_tarif` (
  `id` int(11) NOT NULL,
  `prix_par_minute` decimal(10,2) NOT NULL DEFAULT 10.00,
  `updated_by` int(11) DEFAULT NULL COMMENT 'FK → users.id',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `li_articles`
--

CREATE TABLE `li_articles` (
  `id` int(11) NOT NULL,
  `reference` varchar(32) NOT NULL,
  `titre` varchar(500) NOT NULL,
  `chapeau` varchar(1200) DEFAULT NULL,
  `image_principale` varchar(800) DEFAULT NULL COMMENT 'URL de la vignette principale (thumbnail)',
  `contenu` longtext DEFAULT NULL,
  `categorie_id` int(11) DEFAULT NULL,
  `auteur_id` int(11) NOT NULL,
  `relecteur_id` int(11) DEFAULT NULL,
  `statut` enum('brouillon','revision','publie','refuse','archive') DEFAULT 'brouillon',
  `priorite` enum('normale','importante','urgente','flash') DEFAULT 'normale',
  `tags` text DEFAULT NULL,
  `exclusif` tinyint(1) DEFAULT 0,
  `a_la_une` tinyint(1) DEFAULT 0,
  `confidentiel` tinyint(1) DEFAULT 0,
  `nb_vues` int(11) DEFAULT 0,
  `nb_partages` int(11) DEFAULT 0,
  `nb_likes` int(11) DEFAULT 0,
  `date_deadline` datetime DEFAULT NULL,
  `date_publication` datetime DEFAULT NULL,
  `notes_redaction` text DEFAULT NULL,
  `raison_refus` text DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `li_articles`
--

INSERT INTO `li_articles` (`id`, `reference`, `titre`, `chapeau`, `image_principale`, `contenu`, `categorie_id`, `auteur_id`, `relecteur_id`, `statut`, `priorite`, `tags`, `exclusif`, `a_la_une`, `confidentiel`, `nb_vues`, `nb_partages`, `nb_likes`, `date_deadline`, `date_publication`, `notes_redaction`, `raison_refus`, `created_by`, `created_at`, `updated_at`) VALUES
