CREATE TABLE `li_articles_full` (
`id` int(11)
,`reference` varchar(32)
,`titre` varchar(500)
,`chapeau` varchar(1200)
,`contenu` longtext
,`categorie_id` int(11)
,`auteur_id` int(11)
,`relecteur_id` int(11)
,`statut` enum('brouillon','revision','publie','refuse','archive')
,`priorite` enum('normale','importante','urgente','flash')
,`tags` text
,`exclusif` tinyint(1)
,`a_la_une` tinyint(1)
,`confidentiel` tinyint(1)
,`nb_vues` int(11)
,`nb_partages` int(11)
,`nb_likes` int(11)
,`date_deadline` datetime
,`date_publication` datetime
,`notes_redaction` text
,`raison_refus` text
,`created_by` int(11)
,`created_at` timestamp
,`updated_at` timestamp
,`cat_nom` varchar(120)
,`cat_couleur` varchar(20)
,`cat_icone` varchar(60)
,`auteur_nom` varchar(100)
);

