--
-- Structure de la table `lsc_fourriere`
--

CREATE TABLE `lsc_fourriere` (
  `id` int(10) UNSIGNED NOT NULL,
  `profile_id` int(11) DEFAULT NULL COMMENT 'FK → profiles.id',
  `civil_name` varchar(200) NOT NULL DEFAULT '',
  `plaque` varchar(20) NOT NULL,
  `modele` varchar(100) NOT NULL,
  `heure_entree` datetime NOT NULL,
  `heure_sortie` datetime DEFAULT NULL,
  `statut` enum('en_fourriere','sorti') NOT NULL DEFAULT 'en_fourriere',
  `montant_facture` decimal(10,2) DEFAULT NULL,
  `employe_entree_id` int(11) DEFAULT NULL,
  `employe_sortie_id` int(11) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsc_fourriere_tarif`
--

CREATE TABLE `lsc_fourriere_tarif` (
  `id` int(10) UNSIGNED NOT NULL,
  `prix_par_minute` decimal(8,4) NOT NULL DEFAULT 5.0000,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_activity_logs`
--

CREATE TABLE `lsfd_activity_logs` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `action_type` varchar(60) DEFAULT NULL,
  `resource_type` varchar(60) DEFAULT NULL,
  `resource_id` int(11) DEFAULT NULL,
  `description` varchar(500) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_announcements`
--

CREATE TABLE `lsfd_announcements` (
  `id` int(10) UNSIGNED NOT NULL,
  `title` varchar(200) NOT NULL,
  `body` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_apparatus`
--

CREATE TABLE `lsfd_apparatus` (
  `id` int(10) UNSIGNED NOT NULL,
  `plate` varchar(40) DEFAULT NULL,
  `name` varchar(80) DEFAULT NULL,
  `type` varchar(40) NOT NULL DEFAULT 'pompe',
  `station` varchar(60) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'service',
  `assigned_to` int(11) DEFAULT NULL,
  `mileage` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_apparatus_maintenance`
--

CREATE TABLE `lsfd_apparatus_maintenance` (
  `id` int(10) UNSIGNED NOT NULL,
  `apparatus_id` int(10) UNSIGNED NOT NULL,
  `kind` varchar(30) NOT NULL DEFAULT 'panne',
  `description` text DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ouvert',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_fire_investigations`
--

CREATE TABLE `lsfd_fire_investigations` (
  `id` int(10) UNSIGNED NOT NULL,
  `report_id` int(10) UNSIGNED DEFAULT NULL,
  `incident_id` int(10) UNSIGNED DEFAULT NULL,
  `cause` varchar(40) NOT NULL DEFAULT 'indeterminee',
  `findings` longtext DEFAULT NULL,
  `evidence` longtext DEFAULT NULL,
  `suspects` longtext DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'en_cours',
  `transmitted_lspd` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_hazmat`
--

CREATE TABLE `lsfd_hazmat` (
  `id` int(10) UNSIGNED NOT NULL,
  `un_code` varchar(20) DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `risks` text DEFAULT NULL,
  `procedure` text DEFAULT NULL,
  `epi_required` varchar(255) DEFAULT NULL,
  `zone` varchar(150) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_incidents`
--

CREATE TABLE `lsfd_incidents` (
  `id` int(10) UNSIGNED NOT NULL,
  `ref` varchar(30) DEFAULT NULL,
  `category` varchar(40) NOT NULL DEFAULT 'incendie',
  `type` varchar(120) NOT NULL,
  `priority` varchar(20) NOT NULL DEFAULT 'normale',
  `address` varchar(255) DEFAULT NULL,
  `coords` varchar(80) DEFAULT NULL,
  `caller_name` varchar(150) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `radio_channel` varchar(40) DEFAULT NULL,
  `station` varchar(60) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ouvert',
  `apparatus` longtext DEFAULT NULL,
  `injured` tinyint(1) NOT NULL DEFAULT 0,
  `time_call` datetime DEFAULT NULL,
  `time_depart` datetime DEFAULT NULL,
  `time_arrival` datetime DEFAULT NULL,
  `time_closed` datetime DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_incident_units`
--

CREATE TABLE `lsfd_incident_units` (
  `id` int(10) UNSIGNED NOT NULL,
  `incident_id` int(10) UNSIGNED NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `role` varchar(60) DEFAULT NULL,
  `unit_status` varchar(30) NOT NULL DEFAULT 'en_route',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_inspections`
--

CREATE TABLE `lsfd_inspections` (
  `id` int(10) UNSIGNED NOT NULL,
  `establishment` varchar(180) NOT NULL,
  `address` varchar(255) DEFAULT NULL,
  `kind` varchar(40) NOT NULL DEFAULT 'inspection',
  `nonconformities` text DEFAULT NULL,
  `deadline` date DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'en_cours',
  `certificate` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_inventory`
--

CREATE TABLE `lsfd_inventory` (
  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(120) NOT NULL,
  `category` varchar(40) NOT NULL DEFAULT 'consommable',
  `station` varchar(60) DEFAULT NULL,
  `quantity` int(11) NOT NULL DEFAULT 0,
  `threshold` int(11) NOT NULL DEFAULT 0,
  `assigned_to` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_pcr`
--

CREATE TABLE `lsfd_pcr` (
  `id` int(10) UNSIGNED NOT NULL,
  `incident_id` int(10) UNSIGNED DEFAULT NULL,
  `patient_id` int(11) DEFAULT NULL,
  `arrival_state` text DEFAULT NULL,
  `initial_assessment` text DEFAULT NULL,
  `actions` text DEFAULT NULL,
  `medications` text DEFAULT NULL,
  `evolution` text DEFAULT NULL,
  `outcome` varchar(40) NOT NULL DEFAULT 'stabilise',
  `transmitted_sams` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_reports`
--

CREATE TABLE `lsfd_reports` (
  `id` int(10) UNSIGNED NOT NULL,
  `incident_id` int(10) UNSIGNED DEFAULT NULL,
  `title` varchar(200) DEFAULT NULL,
  `type` varchar(60) NOT NULL DEFAULT 'Intervention',
  `tags` longtext DEFAULT NULL,
  `summary` longtext DEFAULT NULL,
  `causes` text DEFAULT NULL,
  `victims` longtext DEFAULT NULL,
  `damages` text DEFAULT NULL,
  `resources` text DEFAULT NULL,
  `observations` text DEFAULT NULL,
  `suspect_crime` tinyint(1) NOT NULL DEFAULT 0,
  `signatures` longtext DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsfd_report_tags`
--

CREATE TABLE `lsfd_report_tags` (
  `id` int(10) UNSIGNED NOT NULL,
  `label` varchar(100) NOT NULL,
  `color` varchar(7) NOT NULL DEFAULT '#dc2626',
