--
-- Structure de la table `lsm_categories`
--

CREATE TABLE `lsm_categories` (
  `id` int(11) NOT NULL,
  `nom` varchar(100) NOT NULL,
  `slug` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `couleur` varchar(7) DEFAULT '#ef4444',
  `icone` varchar(50) DEFAULT 'fa-car',
  `ordre` int(11) DEFAULT 0,
  `actif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_clients`
--

CREATE TABLE `lsm_clients` (
  `id` int(11) NOT NULL,
  `nom` varchar(255) NOT NULL,
  `prenom` varchar(255) DEFAULT NULL,
  `telephone` varchar(50) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `adresse` text DEFAULT NULL,
  `type` enum('particulier','entreprise','vip') DEFAULT 'particulier',
  `numero_permis` varchar(100) DEFAULT NULL,
  `date_naissance` date DEFAULT NULL,
  `nb_achats` int(11) DEFAULT 0,
  `total_depense` decimal(12,2) DEFAULT 0.00,
  `dernier_achat` date DEFAULT NULL,
  `notes` text DEFAULT NULL COMMENT 'Notes internes sur le client',
  `vip` tinyint(1) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_essais`
--

CREATE TABLE `lsm_essais` (
  `id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `vehicule_id` int(11) NOT NULL,
  `date_rdv` datetime NOT NULL,
  `duree_minutes` int(11) DEFAULT 30,
  `statut` enum('planifie','en_cours','termine','annule') DEFAULT 'planifie',
  `vendeur_accompagnant` int(11) DEFAULT NULL COMMENT 'Vendeur qui accompagne',
  `resultat` enum('interesse','pas_interesse','a_reflechi') DEFAULT NULL COMMENT 'Résultat de l''essai',
  `notes` text DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_maintenances`
--

CREATE TABLE `lsm_maintenances` (
  `id` int(11) NOT NULL,
  `vehicule_id` int(11) NOT NULL,
  `type` enum('revision','reparation','controle','preparation_vente') DEFAULT 'revision',
  `description` text NOT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date DEFAULT NULL,
  `cout` decimal(10,2) DEFAULT 0.00,
  `pieces_remplacees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pieces_remplacees`)),
  `statut` enum('en_attente','en_cours','terminee') DEFAULT 'en_attente',
  `technicien` varchar(255) DEFAULT NULL,
  `garage` varchar(255) DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_marques`
--

CREATE TABLE `lsm_marques` (
  `id` int(11) NOT NULL,
  `nom` varchar(100) NOT NULL,
  `pays_origine` varchar(100) DEFAULT NULL,
  `logo_url` varchar(500) DEFAULT NULL,
  `actif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_plaques`
--

CREATE TABLE `lsm_plaques` (
  `id` int(11) NOT NULL,
  `numero_plaque` varchar(50) NOT NULL,
  `vente_id` int(11) NOT NULL,
  `vehicule_id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `type` enum('standard','personnalisee','temporaire') DEFAULT 'standard',
  `date_demande` date NOT NULL,
  `date_attribution` date DEFAULT NULL,
  `date_installation` date DEFAULT NULL,
  `statut` enum('en_attente','attribuee','installee','annulee') DEFAULT 'en_attente',
  `organisme_delivrance` varchar(255) DEFAULT 'DMV Los Santos',
  `cout_plaque` decimal(10,2) DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `declare_par` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

