,`declare_par_nom` varchar(100)
);

-- --------------------------------------------------------

--
-- Structure de la table `lsm_reprises`
--

CREATE TABLE `lsm_reprises` (
  `id` int(11) NOT NULL,
  `dealership_key` varchar(64) NOT NULL DEFAULT 'LS_MOTORS',
  `vente_id` int(11) DEFAULT NULL COMMENT 'Vente associée (si applicable)',
  `client_id` int(11) NOT NULL,
  `marque` varchar(255) NOT NULL,
  `modele` varchar(255) NOT NULL,
  `annee` int(11) DEFAULT NULL,
  `kilometrage` int(11) DEFAULT NULL,
  `etat_general` enum('excellent','bon','moyen','mauvais') DEFAULT 'bon',
  `prix_estime` decimal(12,2) DEFAULT NULL,
  `prix_propose` decimal(12,2) DEFAULT NULL,
  `prix_accepte` decimal(12,2) DEFAULT NULL,
  `statut` enum('evaluation','proposee','acceptee','refusee') DEFAULT 'evaluation',
  `expertise_faite` tinyint(1) DEFAULT 0,
  `expertise_notes` text DEFAULT NULL,
  `photos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`photos`)),
  `evalue_par` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_sequences`
--

CREATE TABLE `lsm_sequences` (
  `dealership_key` varchar(64) NOT NULL DEFAULT 'LS_MOTORS',
  `type` enum('VEH','VTE','PLQ') NOT NULL,
  `annee` int(11) NOT NULL,
  `dernier` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

