  `revenus_total` decimal(12,2) DEFAULT 0.00,
  `marge_total` decimal(12,2) DEFAULT 0.00,
  `nb_essais` int(11) DEFAULT 0,
  `nb_reprises` int(11) DEFAULT 0,
  `stock_disponible` int(11) DEFAULT 0,
  `valeur_stock` decimal(12,2) DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

