,`vendeur_nom` varchar(100)
,`nb_ventes` bigint(21)
,`total_ventes` decimal(34,2)
,`total_commissions` decimal(34,2)
,`panier_moyen` decimal(16,6)
,`derniere_vente` timestamp
);

