--
-- Doublure de structure pour la vue `lsm_stock_disponible`
-- (Voir ci-dessous la vue réelle)
--
CREATE TABLE `lsm_stock_disponible` (
`id` int(11)
,`reference` varchar(50)
,`marque_id` int(11)
,`categorie_id` int(11)
,`modele` varchar(255)
,`annee` int(11)
,`couleur` varchar(100)
,`prix_achat` decimal(12,2)
,`prix_vente` decimal(12,2)
,`marge` decimal(12,2)
,`marge_pct` decimal(5,2)
,`kilometrage` int(11)
,`nb_places` int(11)
,`puissance_cv` int(11)
,`type_carburant` enum('essence','diesel','electrique','hybride')
,`boite` enum('manuelle','automatique','semi-auto')
,`etat` enum('neuf','occasion','collection')
,`statut` enum('disponible','reserve','vendu','maintenance')
,`description` text
,`equipements` longtext
,`images` longtext
,`stock_location` varchar(255)
,`date_arrivee` date
,`date_mise_vente` date
,`vendu_le` date
,`ajout_par` int(11)
,`created_at` timestamp
,`updated_at` timestamp
,`marque_nom` varchar(100)
,`categorie_nom` varchar(100)
,`categorie_couleur` varchar(7)
,`ajout_par_nom` varchar(100)
,`jours_en_vente` int(8)
);

