--
-- Structure de la table `lsm_vehicules`
--

CREATE TABLE `lsm_vehicules` (
  `id` int(11) NOT NULL,
  `dealership_key` varchar(64) NOT NULL DEFAULT 'LS_MOTORS',
  `reference` varchar(50) NOT NULL,
  `marque_id` int(11) DEFAULT NULL,
  `categorie_id` int(11) DEFAULT NULL,
  `modele` varchar(255) NOT NULL,
  `annee` int(11) DEFAULT NULL,
  `couleur` varchar(100) DEFAULT NULL,
  `prix_achat` decimal(12,2) DEFAULT NULL COMMENT 'Prix d''achat du véhicule',
  `prix_vente` decimal(12,2) NOT NULL COMMENT 'Prix de vente public',
  `marge` decimal(12,2) DEFAULT NULL COMMENT 'Marge = prix_vente - prix_achat',
  `marge_pct` decimal(5,2) DEFAULT NULL COMMENT 'Marge en pourcentage',
  `kilometrage` int(11) DEFAULT 0,
  `nb_places` int(11) DEFAULT 5,
  `puissance_cv` int(11) DEFAULT NULL,
  `type_carburant` enum('essence','diesel','electrique','hybride') DEFAULT 'essence',
  `boite` enum('manuelle','automatique','semi-auto') DEFAULT 'manuelle',
  `etat` enum('neuf','occasion','collection') DEFAULT 'neuf',
  `statut` enum('disponible','reserve','vendu','maintenance') DEFAULT 'disponible',
  `description` text DEFAULT NULL,
  `equipements` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste des équipements' CHECK (json_valid(`equipements`)),
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'URLs des images' CHECK (json_valid(`images`)),
  `stock_location` varchar(255) DEFAULT NULL COMMENT 'Emplacement dans le showroom',
  `date_arrivee` date DEFAULT NULL,
  `date_mise_vente` date DEFAULT NULL,
  `vendu_le` date DEFAULT NULL,
  `ajout_par` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `lsm_ventes`
--

CREATE TABLE `lsm_ventes` (
  `id` int(11) NOT NULL,
  `reference` varchar(50) NOT NULL,
  `vehicule_id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `vendeur_id` int(11) NOT NULL COMMENT 'ID du vendeur (user)',
  `prix_final` decimal(12,2) NOT NULL,
  `remise` decimal(12,2) DEFAULT 0.00,
  `remise_pct` decimal(5,2) DEFAULT 0.00,
  `mode_paiement` enum('comptant','credit','leasing','autre') DEFAULT 'comptant',
  `acompte` decimal(12,2) DEFAULT 0.00,
  `commission_vendeur` decimal(12,2) DEFAULT NULL,
  `commission_pct` decimal(5,2) DEFAULT 5.00,
  `contrat_signe` tinyint(1) DEFAULT 0,
  `date_signature` date DEFAULT NULL,
  `numero_contrat` varchar(100) DEFAULT NULL,
  `date_livraison` date DEFAULT NULL,
  `livraison_effectuee` tinyint(1) DEFAULT 0,
  `lieu_livraison` varchar(500) DEFAULT NULL,
  `garantie_mois` int(11) DEFAULT 12,
  `garantie_km` int(11) DEFAULT 20000,
  `services_inclus` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Services additionnels inclus' CHECK (json_valid(`services_inclus`)),
  `statut` enum('en_cours','validee','livree','annulee') DEFAULT 'en_cours',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Doublure de structure pour la vue `lsm_ventes_mois`
-- (Voir ci-dessous la vue réelle)
--
CREATE TABLE `lsm_ventes_mois` (
`id` int(11)
,`reference` varchar(50)
,`vehicule_id` int(11)
,`client_id` int(11)
,`vendeur_id` int(11)
,`prix_final` decimal(12,2)
,`remise` decimal(12,2)
,`remise_pct` decimal(5,2)
,`mode_paiement` enum('comptant','credit','leasing','autre')
,`acompte` decimal(12,2)
,`commission_vendeur` decimal(12,2)
,`commission_pct` decimal(5,2)
,`contrat_signe` tinyint(1)
,`date_signature` date
,`numero_contrat` varchar(100)
,`date_livraison` date
,`livraison_effectuee` tinyint(1)
,`lieu_livraison` varchar(500)
,`garantie_mois` int(11)
,`garantie_km` int(11)
,`services_inclus` longtext
,`statut` enum('en_cours','validee','livree','annulee')
,`notes` text
,`created_at` timestamp
,`updated_at` timestamp
,`vehicule_modele` varchar(255)
,`marque_nom` varchar(100)
,`client_nom` varchar(255)
,`vendeur_nom` varchar(100)
,`marge_reelle` decimal(13,2)
);

