-- Déchargement des données de la table `lspd_equipment`
--

INSERT INTO `lspd_equipment` (`id`, `officer_id`, `equipment_type`, `serial_number`, `date_assigned`, `date_returned`, `condition_status`, `notes`, `status`, `created_at`, `updated_at`, `images`) VALUES
