--
-- Structure de la table `mdt_roles`
--

CREATE TABLE `mdt_roles` (
  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(50) NOT NULL COMMENT 'Clé interne, ex: Staff',
  `display_name` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `color` varchar(20) NOT NULL DEFAULT '#64748b',
  `icon` varchar(50) NOT NULL DEFAULT 'shield',
  `hierarchy_level` smallint(6) NOT NULL DEFAULT 0 COMMENT 'Plus élevé = plus de pouvoir',
  `discord_role_id` varchar(30) DEFAULT NULL COMMENT 'ID du rôle Discord lié',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Rôle attribué par défaut',
  `is_staff_panel` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Donne accès au panel staff',
  `can_view_all_panels` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Si 1, le rôle voit tous les panels actifs en lecture seule (mode démo)',
  `discord_sync_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Participe à la sync Discord',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `max_characters` int(11) NOT NULL DEFAULT 3
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

