--
-- Structure de la table `medical_certificates`
--

CREATE TABLE `medical_certificates` (
  `id` int(11) NOT NULL,
  `type` enum('arret_travail','aptitude','traumatisme','naissance','psy_suivi','psy_eval','aptitude_ppa') NOT NULL,
  `patient_id` int(11) NOT NULL,
  `doctor_id` int(11) NOT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Données spécifiques au type de certificat' CHECK (json_valid(`data`)),
  `description_rich` text DEFAULT NULL,
  `valid_from` date DEFAULT NULL,
  `valid_until` date DEFAULT NULL,
  `status` enum('active','expired','cancelled') DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `google_docs_url` varchar(500) DEFAULT NULL COMMENT 'Lien vers le Google Doc généré'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déclencheurs `medical_certificates`
--
DELIMITER $$
CREATE TRIGGER `update_certificate_status_before_update` BEFORE UPDATE ON `medical_certificates` FOR EACH ROW BEGIN
    IF NEW.valid_until < CURDATE() AND NEW.status = 'active' THEN
        SET NEW.status = 'expired';
    END IF;
END
$$
DELIMITER ;

