-- --------------------------------------------------------

--
-- Structure de la table `pearls_reservations`
--

CREATE TABLE `pearls_reservations` (
  `id` int(10) UNSIGNED NOT NULL,
  `room_id` int(10) UNSIGNED NOT NULL,
  `client_name` varchar(150) NOT NULL,
  `client_phone` varchar(30) DEFAULT NULL,
  `client_id` int(10) UNSIGNED DEFAULT NULL,
  `check_in` date NOT NULL,
  `check_out` date NOT NULL,
  `nights` tinyint(3) UNSIGNED GENERATED ALWAYS AS (to_days(`check_out`) - to_days(`check_in`)) STORED,
  `total_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `status` enum('confirmée','en cours','terminée','annulée','no-show') NOT NULL DEFAULT 'confirmée',
  `notes` text DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `pearls_rooms`
--

CREATE TABLE `pearls_rooms` (
  `id` int(10) UNSIGNED NOT NULL,
  `room_number` varchar(10) NOT NULL,
  `room_type` enum('Standard','Supérieure','Deluxe','Suite','Penthouse') NOT NULL DEFAULT 'Standard',
  `floor` tinyint(3) UNSIGNED NOT NULL DEFAULT 1,
  `capacity` tinyint(3) UNSIGNED NOT NULL DEFAULT 2,
  `price_per_night` decimal(10,2) NOT NULL DEFAULT 0.00,
  `status` enum('libre','occupée','maintenance','nettoyage') NOT NULL DEFAULT 'libre',
  `amenities` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `pearls_services`
--

CREATE TABLE `pearls_services` (
  `id` int(10) UNSIGNED NOT NULL,
  `reservation_id` int(10) UNSIGNED DEFAULT NULL,
  `room_id` int(10) UNSIGNED DEFAULT NULL,
  `service_type` enum('Room Service','Spa','Restaurant','Blanchisserie','Bar','Autre') NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `served_by` int(10) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `penal_code`
--

CREATE TABLE `penal_code` (
  `id` int(11) NOT NULL,
  `code` varchar(50) NOT NULL COMMENT 'Ex: PC 487',
  `category` enum('crime','delit_majeur','delit_mineur','infraction') NOT NULL DEFAULT 'infraction',
  `title` varchar(255) NOT NULL,
  `description_rich` text NOT NULL,
  `severity` int(11) DEFAULT 1 COMMENT '1-5',
  `min_fine` decimal(10,2) DEFAULT 0.00,
  `max_fine` decimal(10,2) DEFAULT 0.00,
  `min_jail_months` int(11) DEFAULT 0,
  `max_jail_months` int(11) DEFAULT 0,
  `points` int(11) DEFAULT 0 COMMENT 'Points permis',
  `is_arrestable` tinyint(1) DEFAULT 0,
  `is_warrantable` tinyint(1) DEFAULT 0,
  `examples` text DEFAULT NULL COMMENT 'Exemples d''application',
  `related_codes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Codes liés' CHECK (json_valid(`related_codes`)),
  `active` tinyint(1) DEFAULT 1,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `nom_code` varchar(200) DEFAULT NULL,
  `gravity_fines` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gravity_fines`)),
  `gravity_up` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`gravity_up`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

