--
-- Structure de la table `postop_orders`
--

CREATE TABLE `postop_orders` (
  `id` int(11) NOT NULL,
  `customer_name` varchar(255) NOT NULL COMMENT 'Nom du client ou entreprise',
  `order_time` datetime NOT NULL COMMENT 'Heure de commande',
  `delivery_time` datetime DEFAULT NULL COMMENT 'Heure de livraison prévue',
  `delivery_location` varchar(500) NOT NULL COMMENT 'Lieu de livraison',
  `delivery_fee` decimal(10,2) DEFAULT 0.00 COMMENT 'Frais de livraison',
  `employee_name` varchar(255) NOT NULL COMMENT 'Employé qui a pris la commande',
  `status` enum('preparation','waiting','delivered') DEFAULT 'preparation' COMMENT 'En préparation / En attente / Livré',
  `total_amount` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT 'Montant total de la commande',
  `notes` text DEFAULT NULL COMMENT 'Notes supplémentaires',
  `created_by` int(11) NOT NULL COMMENT 'ID de l''utilisateur qui a créé',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `delivered_at` datetime DEFAULT NULL COMMENT 'Date/heure de livraison effective'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

