--
-- Structure de la table `postop_order_items`
--

CREATE TABLE `postop_order_items` (
  `id` int(11) NOT NULL,
  `order_id` int(11) NOT NULL,
  `article_id` int(11) NOT NULL,
  `quantity` int(11) NOT NULL DEFAULT 1,
  `unit_price` decimal(10,2) NOT NULL COMMENT 'Prix unitaire au moment de la commande',
  `subtotal` decimal(10,2) NOT NULL COMMENT 'Sous-total (quantity * unit_price)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

