--
-- Structure de la table `pregnancy_tracking`
--

CREATE TABLE `pregnancy_tracking` (
  `id` int(11) NOT NULL,
  `patient_id` int(11) NOT NULL,
  `doctor_id` int(11) NOT NULL,
  `conception_date` date NOT NULL,
  `due_date` date NOT NULL,
  `current_week` int(11) DEFAULT 0,
  `trimester` int(11) DEFAULT 1,
  `notes_rich` text DEFAULT NULL,
  `appointments` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Historique des rendez-vous' CHECK (json_valid(`appointments`)),
  `measurements` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Poids, tension, etc.' CHECK (json_valid(`measurements`)),
  `complications` text DEFAULT NULL,
  `status` enum('ongoing','completed','terminated') DEFAULT 'ongoing',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `google_docs_url` varchar(500) DEFAULT NULL COMMENT 'Lien vers le Google Doc généré'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

