--
-- Structure de la table `profiles`
--

CREATE TABLE `profiles` (
  `id` int(11) NOT NULL,
  `firstname` varchar(100) NOT NULL,
  `lastname` varchar(100) NOT NULL,
  `iban` varchar(34) DEFAULT NULL,
  `nationality` varchar(100) DEFAULT NULL,
  `age` int(3) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `job` varchar(100) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `license_car` tinyint(1) DEFAULT 0,
  `license_ppa` tinyint(1) DEFAULT 0,
  `license_boat` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Permis Bateau',
  `license_plane` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Permis Avion',
  `tags` text DEFAULT NULL COMMENT 'JSON array',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `blood_type` varchar(5) DEFAULT NULL COMMENT 'Groupe sanguin (A+, A-, B+, B-, AB+, AB-, O+, O-)',
  `avatar` varchar(500) DEFAULT NULL,
  `email` varchar(190) DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `appartenance` varchar(120) DEFAULT NULL,
  `eye_color` varchar(40) DEFAULT NULL,
  `gender` varchar(10) DEFAULT NULL,
  `has_scar` tinyint(1) NOT NULL DEFAULT 0,
  `scar_location` varchar(160) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

