--
-- Structure de la table `reports`
--

CREATE TABLE `reports` (
  `id` int(11) NOT NULL,
  `type` varchar(100) NOT NULL,
  `tags` text DEFAULT NULL COMMENT 'JSON array',
  `evidence` text DEFAULT NULL COMMENT 'JSON array of images',
  `officers` text DEFAULT NULL COMMENT 'JSON array of officer IDs',
  `civilians` text DEFAULT NULL COMMENT 'JSON array of civilian profile IDs',
  `witnesses` text DEFAULT NULL COMMENT 'JSON array of witness profile IDs',
  `description` longtext DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `faction` enum('LSPD','LSSD','DOJ','USSS','SAMS') DEFAULT NULL,
  `status` enum('draft','submitted','reviewing','closed') NOT NULL DEFAULT 'submitted',
  `priority` enum('low','normal','high','critical') NOT NULL DEFAULT 'normal',
  `location` varchar(255) DEFAULT NULL,
  `incident_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `title` varchar(255) DEFAULT NULL,
  `officers_involved` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'IDs des officiers impliqués' CHECK (json_valid(`officers_involved`)),
  `suspects` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'IDs des suspects' CHECK (json_valid(`suspects`)),
  `vehicles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`vehicles`)),
  `description_rich` text DEFAULT NULL COMMENT 'Description avec formatage HTML',
  `internal_notes` text DEFAULT NULL,
  `doj_infractions` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Déchargement des données de la table `reports`
--

