  `citizen_id` int(11) NOT NULL,
  `sentence_type` enum('prison','probation','community_service','fine','suspended') NOT NULL,
  `duration_months` int(11) DEFAULT 0 COMMENT 'Durée en mois',
  `duration_hours` int(11) DEFAULT 0 COMMENT 'Heures de travaux',
