-- --------------------------------------------------------

--
-- Structure de la table `usss_agents`
--

CREATE TABLE `usss_agents` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL COMMENT 'Référence à users.id',
  `badge_number` varchar(20) NOT NULL,
  `nom_rp` varchar(100) NOT NULL,
  `prenom_rp` varchar(100) NOT NULL,
  `photo` varchar(255) DEFAULT NULL,
  `grade` varchar(100) NOT NULL COMMENT 'Special Agent, Senior Agent, Supervisory Agent, SAIC, etc.',
  `division_id` int(11) DEFAULT NULL,
  `superieur_id` int(11) DEFAULT NULL COMMENT 'ID agent supérieur hiérarchique',
  `date_entree` date NOT NULL,
  `statut` enum('EN_SERVICE','HORS_SERVICE','CONGE','SUSPENSION','ENQUETE_INTERNE','DEMISSION') DEFAULT 'EN_SERVICE',
  `heures_service` int(11) DEFAULT 0 COMMENT 'Heures totales de service',
  `niveau_habilitation` enum('CONFIDENTIEL','SECRET','TOP_SECRET') DEFAULT 'CONFIDENTIEL',
  `specialisations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste certifications: ["SNIPER","NEGOCIATEUR","CYBER","PROTECTION_RAPPROCHEE"]' CHECK (json_valid(`specialisations`)),
  `evaluations_notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Historique évaluations' CHECK (json_valid(`evaluations_notes`)),
  `sanctions` int(11) DEFAULT 0 COMMENT 'Nombre total de sanctions',
  `rapport_psychologique` text DEFAULT NULL,
  `notes_internes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_annonces`
--

CREATE TABLE `usss_annonces` (
  `id` int(11) NOT NULL,
  `titre` varchar(255) NOT NULL,
  `contenu` text NOT NULL,
  `niveau_importance` enum('INFORMATION','IMPORTANT','URGENT','ALERTE') DEFAULT 'INFORMATION',
  `visible_divisions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste IDs divisions concernées (null = tous)' CHECK (json_valid(`visible_divisions`)),
  `visible_grades` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste grades concernés (null = tous)' CHECK (json_valid(`visible_grades`)),
  `auteur_id` int(11) NOT NULL,
  `date_publication` datetime NOT NULL,
  `date_expiration` datetime DEFAULT NULL,
  `actif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_crimes_financiers`
--

CREATE TABLE `usss_crimes_financiers` (
  `id` int(11) NOT NULL,
  `reference` varchar(50) NOT NULL,
  `dossier_id` int(11) DEFAULT NULL,
  `type` enum('BLANCHIMENT','FAUX_BILLETS','FRAUDE_BANCAIRE','ESCROQUERIE','CRYPTO_MONNAIE') NOT NULL,
  `suspect_nom` varchar(255) NOT NULL,
  `montant_estime` decimal(15,2) DEFAULT 0.00,
  `comptes_impliques` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste comptes bancaires' CHECK (json_valid(`comptes_impliques`)),
  `transactions_suspectes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Historique transactions' CHECK (json_valid(`transactions_suspectes`)),
  `comptes_geles` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Comptes gelés' CHECK (json_valid(`comptes_geles`)),
  `saisies_effectuees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Biens saisis' CHECK (json_valid(`saisies_effectuees`)),
  `agent_enqueteur` int(11) NOT NULL,
  `statut` enum('ENQUETE','GELE','SAISI','TRANSMIS_DOJ','CLASSE') DEFAULT 'ENQUETE',
  `rapport` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_divisions`
--

CREATE TABLE `usss_divisions` (
  `id` int(11) NOT NULL,
  `nom` varchar(100) NOT NULL,
  `code` varchar(20) NOT NULL COMMENT 'Ex: PPD, FCD, ISD',
  `description` text DEFAULT NULL,
  `chef_division` int(11) DEFAULT NULL COMMENT 'ID user chef de division',
  `budget_alloue` decimal(12,2) DEFAULT 0.00,
  `niveau_securite` enum('PUBLIC','CONFIDENTIEL','SECRET','TOP_SECRET') DEFAULT 'CONFIDENTIEL',
  `effectif_actuel` int(11) DEFAULT 0,
  `ordre` int(11) DEFAULT 0,
  `actif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_dossiers`
--

CREATE TABLE `usss_dossiers` (
  `id` int(11) NOT NULL,
  `reference` varchar(50) NOT NULL COMMENT 'Ex: USSS-2026-00145',
  `titre` varchar(255) NOT NULL,
  `type` enum('FINANCIER','TERRORISME','ENLEVEMENT','CORRUPTION','TRAFIC','MENACE_VIP','CYBERCRIME','CONTREFACON','AUTRE') NOT NULL,
  `priorite` enum('FAIBLE','MOYENNE','HAUTE','CRITIQUE') DEFAULT 'MOYENNE',
  `niveau_classification` enum('PUBLIC_INTERNE','CONFIDENTIEL','SECRET','TOP_SECRET') DEFAULT 'CONFIDENTIEL',
  `division_responsable` int(11) DEFAULT NULL,
  `agent_responsable` int(11) NOT NULL COMMENT 'Agent en charge du dossier',
  `agents_assignes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste IDs agents assignés' CHECK (json_valid(`agents_assignes`)),
  `suspects` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste suspects avec infos' CHECK (json_valid(`suspects`)),
  `temoignages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Témoignages recueillis' CHECK (json_valid(`temoignages`)),
  `preuves` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste preuves avec URLs fichiers' CHECK (json_valid(`preuves`)),
  `description` text NOT NULL,
  `rapport_evolution` text DEFAULT NULL COMMENT 'Rapport d''avancement',
  `statut` enum('OUVERT','EN_ATTENTE','EN_COURS','RESOLU','CLASSE','TRANSMIS_DOJ') DEFAULT 'OUVERT',
  `date_ouverture` date NOT NULL,
  `date_cloture` date DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_dossiers_timeline`
--

CREATE TABLE `usss_dossiers_timeline` (
  `id` int(11) NOT NULL,
  `dossier_id` int(11) NOT NULL,
  `date_evenement` datetime NOT NULL,
  `type_evenement` enum('CREATION','MODIFICATION','SUSPECT_AJOUTE','PREUVE_AJOUTEE','TEMOIGNAGE','PERQUISITION','ARRESTATION','TRANSMISSION','CLASSEMENT') NOT NULL,
  `description` text NOT NULL,
  `agent_id` int(11) NOT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Données additionnelles' CHECK (json_valid(`details`)),
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_formations`
--

CREATE TABLE `usss_formations` (
  `id` int(11) NOT NULL,
  `nom` varchar(255) NOT NULL,
  `type` enum('THEORIQUE','PRATIQUE','CERTIFICATION','RECYCLAGE') NOT NULL,
  `specialisation` varchar(100) DEFAULT NULL COMMENT 'SNIPER, NEGOCIATEUR, CYBER, PROTECTION_RAPPROCHEE',
  `description` text DEFAULT NULL,
  `duree_heures` int(11) NOT NULL,
  `formateur_id` int(11) DEFAULT NULL,
  `note_minimale` decimal(5,2) DEFAULT 70.00,
  `validite_mois` int(11) DEFAULT NULL COMMENT 'Durée validité certification',
  `actif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_formations_resultats`
--

CREATE TABLE `usss_formations_resultats` (
  `id` int(11) NOT NULL,
  `formation_id` int(11) NOT NULL,
  `agent_id` int(11) NOT NULL,
  `date_formation` date NOT NULL,
  `note_obtenue` decimal(5,2) DEFAULT NULL,
  `resultat` enum('EN_COURS','REUSSI','ECHEC','ABSENT') DEFAULT 'EN_COURS',
  `remarques` text DEFAULT NULL,
  `certificat_genere` tinyint(1) DEFAULT 0,
  `date_expiration` date DEFAULT NULL COMMENT 'Date expiration certification',
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_intelligence`
--

CREATE TABLE `usss_intelligence` (
  `id` int(11) NOT NULL,
  `reference` varchar(50) NOT NULL,
  `type` enum('SURVEILLANCE','ECOUTE','INFILTRATION','INFORMATEUR','ANALYSE_COMPORTEMENTALE','TRACKING_GPS') NOT NULL,
  `cible_nom` varchar(255) NOT NULL,
  `cible_details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Infos complètes cible' CHECK (json_valid(`cible_details`)),
  `niveau_menace` enum('FAIBLE','MOYEN','ELEVE','CRITIQUE') DEFAULT 'MOYEN',
  `statut_surveillance` enum('ACTIVE','SUSPENDUE','TERMINEE') DEFAULT 'ACTIVE',
  `agent_responsable` int(11) NOT NULL,
  `division_id` int(11) DEFAULT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date DEFAULT NULL,
  `rapport` text DEFAULT NULL,
  `donnees_collectees` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Données recueillies' CHECK (json_valid(`donnees_collectees`)),
  `localisation_gps` varchar(255) DEFAULT NULL,
  `reseau_criminel` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Graphique relations' CHECK (json_valid(`reseau_criminel`)),
  `notes_confidentielles` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_logs`
--

CREATE TABLE `usss_logs` (
  `id` bigint(20) NOT NULL,
  `user_id` int(11) NOT NULL,
  `action` varchar(100) NOT NULL COMMENT 'CREATE_DOSSIER, MODIFY_AGENT, DELETE_MANDAT, etc.',
  `table_concernee` varchar(100) DEFAULT NULL,
  `enregistrement_id` int(11) DEFAULT NULL,
  `details` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Détails complets de l''action' CHECK (json_valid(`details`)),
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_mandats`
--

CREATE TABLE `usss_mandats` (
  `id` int(11) NOT NULL,
  `reference` varchar(50) NOT NULL COMMENT 'Ex: MW-2026-00042',
  `dossier_id` int(11) DEFAULT NULL,
  `type` enum('ARRET','PERQUISITION','SAISIE','ECOUTE_TELEPHONIQUE','SURVEILLANCE') NOT NULL,
  `cible_nom` varchar(255) NOT NULL,
  `cible_details` text DEFAULT NULL,
  `lieu` varchar(255) DEFAULT NULL COMMENT 'Lieu perquisition/surveillance',
  `motif` text NOT NULL,
  `agent_demandeur` int(11) NOT NULL,
  `juge_valideur` varchar(255) DEFAULT NULL COMMENT 'Nom juge RP',
  `date_emission` date NOT NULL,
  `date_expiration` date DEFAULT NULL,
  `statut` enum('EN_ATTENTE_VALIDATION','ACTIF','EXECUTE','EXPIRE','ANNULE') DEFAULT 'EN_ATTENTE_VALIDATION',
  `date_execution` date DEFAULT NULL,
  `rapport_execution` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_materiel`
--

CREATE TABLE `usss_materiel` (
  `id` int(11) NOT NULL,
  `type` enum('ARME','VEHICULE','EQUIPEMENT_TACTIQUE','ELECTRONIQUE') NOT NULL,
  `nom` varchar(255) NOT NULL,
  `numero_serie` varchar(100) DEFAULT NULL,
  `statut` enum('DISPONIBLE','ASSIGNE','MAINTENANCE','RETIRE') DEFAULT 'DISPONIBLE',
  `agent_assigne` int(11) DEFAULT NULL,
  `date_assignation` date DEFAULT NULL,
  `description` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_messages`
--

CREATE TABLE `usss_messages` (
  `id` int(11) NOT NULL,
  `expediteur_id` int(11) NOT NULL,
  `destinataire_id` int(11) NOT NULL,
  `niveau_classification` enum('NORMAL','CONFIDENTIEL','SECRET','TOP_SECRET') DEFAULT 'NORMAL',
  `sujet` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `lu` tinyint(1) DEFAULT 0,
  `date_lecture` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_niveau_alerte`
--

CREATE TABLE `usss_niveau_alerte` (
  `id` int(11) NOT NULL,
  `niveau` enum('VERT','JAUNE','ORANGE','ROUGE') DEFAULT 'VERT',
  `description` text DEFAULT NULL,
  `modifie_par` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_operations`
--

CREATE TABLE `usss_operations` (
  `id` int(11) NOT NULL,
  `nom_code` varchar(100) NOT NULL COMMENT 'Nom de code opération',
  `description` text NOT NULL,
  `niveau_classification` enum('CONFIDENTIEL','SECRET','TOP_SECRET') DEFAULT 'SECRET',
  `division_responsable` int(11) DEFAULT NULL,
  `chef_operation` int(11) NOT NULL,
  `participants` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Liste IDs agents participants' CHECK (json_valid(`participants`)),
  `objectif` text NOT NULL,
  `date_debut` date NOT NULL,
  `date_fin` date DEFAULT NULL,
  `planning` text DEFAULT NULL COMMENT 'Planning détaillé',
  `documents_classifies` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'URLs documents' CHECK (json_valid(`documents_classifies`)),
  `rapport_final` text DEFAULT NULL,
  `statut` enum('PLANIFIEE','EN_COURS','TERMINEE','ANNULEE','COMPROMISE') DEFAULT 'PLANIFIEE',
  `resultat` enum('SUCCES','ECHEC','PARTIEL') DEFAULT NULL,
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_promotions`
--

CREATE TABLE `usss_promotions` (
  `id` int(11) NOT NULL,
  `agent_id` int(11) NOT NULL,
  `ancien_grade` varchar(100) DEFAULT NULL,
  `nouveau_grade` varchar(100) NOT NULL,
  `ancienne_division` int(11) DEFAULT NULL,
  `nouvelle_division` int(11) DEFAULT NULL,
  `raison` text DEFAULT NULL,
  `approuve_par` int(11) DEFAULT NULL COMMENT 'ID agent qui a validé',
  `date_promotion` date NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_sanctions`
--

CREATE TABLE `usss_sanctions` (
  `id` int(11) NOT NULL,
  `agent_id` int(11) NOT NULL,
  `type_sanction` enum('AVERTISSEMENT','BLAME','MISE_A_PIED','RETROGRADATION','SUSPENSION','RENVOI') NOT NULL,
  `motif` text NOT NULL,
  `duree_jours` int(11) DEFAULT NULL COMMENT 'Durée suspension/mise à pied',
  `emise_par` int(11) NOT NULL COMMENT 'ID agent émetteur',
  `date_sanction` date NOT NULL,
  `statut` enum('ACTIVE','PURGEE','ANNULEE') DEFAULT 'ACTIVE',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `usss_stats_daily`
--

CREATE TABLE `usss_stats_daily` (
  `id` int(11) NOT NULL,
  `date` date NOT NULL,
  `agents_en_service` int(11) DEFAULT 0,
  `operations_actives` int(11) DEFAULT 0,
  `dossiers_ouverts` int(11) DEFAULT 0,
  `mandats_emis` int(11) DEFAULT 0,
  `arrestations` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure de la table `vehicles`
--

CREATE TABLE `vehicles` (
  `id` int(11) NOT NULL,
  `model` varchar(100) NOT NULL,
  `plate` varchar(20) NOT NULL,
  `owner_id` int(11) DEFAULT NULL,
  `color` varchar(100) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `image_url` varchar(500) DEFAULT NULL,
  `status` enum('normal','vole','recherche','suspect','epave','autre') NOT NULL DEFAULT 'normal',
  `status_note` varchar(200) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

