--
-- Doublure de structure pour la vue `v_patients_stats`
-- (Voir ci-dessous la vue réelle)
--
CREATE TABLE `v_patients_stats` (
`id` int(11)
,`firstname` varchar(100)
,`lastname` varchar(100)
,`nb_ordonnances` bigint(21)
,`nb_rapports` bigint(21)
,`nb_certificats` bigint(21)
,`nb_grossesses` bigint(21)
);

-- --------------------------------------------------------

--
-- Doublure de structure pour la vue `v_recent_reports`
-- (Voir ci-dessous la vue réelle)
--
CREATE TABLE `v_recent_reports` (
`id` int(11)
,`type` varchar(100)
,`title` varchar(255)
,`tags` longtext
,`evidence` longtext
,`doctors_involved` longtext
,`patient_id` int(11)
,`description_rich` text
,`created_by` int(11)
,`created_at` timestamp
,`updated_at` timestamp
,`firstname` varchar(100)
,`lastname` varchar(100)
,`creator_name` varchar(100)
);

-- --------------------------------------------------------

--
-- Structure de la table `wanted_persons`
--

CREATE TABLE `wanted_persons` (
  `id` int(11) NOT NULL,
  `profile_id` int(11) NOT NULL,
  `reason` text NOT NULL,
  `level` enum('Faible','Moyen','Élevé','Critique') DEFAULT 'Moyen',
  `created_by` int(11) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `bounty` decimal(10,2) DEFAULT NULL,
  `officer_id` int(11) DEFAULT NULL,
  `description_rich` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

