--
-- Structure de la vue `customized_vehicles`
--
DROP TABLE IF EXISTS `customized_vehicles`;

CREATE ALGORITHM=UNDEFINED DEFINER=`admin_mdt_nexium_off_demo_table`@`%` SQL SECURITY INVOKER VIEW `customized_vehicles`  AS SELECT `vehicle_prices`.`id` AS `id`, `vehicle_prices`.`name` AS `name`, `vehicle_prices`.`category` AS `category`, `vehicle_prices`.`base_price` AS `base_price`, `vehicle_prices`.`description` AS `description`, `vehicle_prices`.`total_mods_percentage` AS `total_mods_percentage`, `vehicle_prices`.`final_price` AS `final_price`, `vehicle_prices`.`mods_count` AS `mods_count` FROM `vehicle_prices` WHERE `vehicle_prices`.`mods_count` > 0 ;

-- --------------------------------------------------------

--
-- Structure de la vue `dynasty_biens_overview`
--
DROP TABLE IF EXISTS `dynasty_biens_overview`;

