CREATE ALGORITHM=UNDEFINED DEFINER=`admin_mdt_nexium_off_demo_table`@`%` SQL SECURITY INVOKER VIEW `taxi_stats_chauffeurs`  AS SELECT `ch`.`id` AS `id`, `ch`.`numero_badge` AS `numero_badge`, `u`.`username` AS `username`, count(case when `c`.`statut` = 'terminee' then 1 end) AS `nb_courses`, sum(case when `c`.`statut` = 'terminee' then `c`.`montant_total` else 0 end) AS `revenus_total`, sum(case when `c`.`statut` = 'terminee' then `c`.`distance_km` else 0 end) AS `distance_totale`, avg(case when `c`.`statut` = 'terminee' then `c`.`note_client` end) AS `note_moyenne`, count(case when `c`.`statut` = 'annulee' then 1 end) AS `courses_annulees` FROM ((`taxi_chauffeurs` `ch` join `users` `u` on(`ch`.`user_id` = `u`.`id`)) left join `taxi_courses` `c` on(`ch`.`id` = `c`.`chauffeur_id`)) GROUP BY `ch`.`id`, `ch`.`numero_badge`, `u`.`username` ;

