CREATE ALGORITHM=UNDEFINED DEFINER=`admin_mdt_nexium_off_demo_table`@`%` SQL SECURITY INVOKER VIEW `v_patients_stats`  AS SELECT `p`.`id` AS `id`, `p`.`firstname` AS `firstname`, `p`.`lastname` AS `lastname`, count(distinct `mp`.`id`) AS `nb_ordonnances`, count(distinct `sr`.`id`) AS `nb_rapports`, count(distinct `mc`.`id`) AS `nb_certificats`, count(distinct `pt`.`id`) AS `nb_grossesses` FROM ((((`profiles` `p` left join `medical_prescriptions` `mp` on(`p`.`id` = `mp`.`patient_id`)) left join `sams_reports` `sr` on(`p`.`id` = `sr`.`patient_id`)) left join `medical_certificates` `mc` on(`p`.`id` = `mc`.`patient_id`)) left join `pregnancy_tracking` `pt` on(`p`.`id` = `pt`.`patient_id`)) GROUP BY `p`.`id` ;

